#!/usr/bin/env bash
# Pi-ter Launcher with "The Creation of Adam" ASCII Animation (Hello PI)

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_DIR="$(cd "$SCRIPT_DIR/.." && pwd)"

# Check non-interactive flags
IS_NON_INTERACTIVE=0
for arg in "$@"; do
    if [[ "$arg" =~ ^(-p|--print|-v|--version|-h|--help)$ ]]; then
        IS_NON_INTERACTIVE=1
        break
    fi
done

if [ "$IS_NON_INTERACTIVE" -eq 0 ] && [ -t 1 ]; then
    tput civis 2>/dev/null || true

    clear

    node -e '
    const frames = [["", "", "  \u001b[38;2;248;250;252m++++*###*+=-.\u001b[0m", "  \u001b[38;2;248;250;252m::::.:=@@@@*#*=-.\u001b[0m", "  \u001b[38;2;248;250;252m.      .-+#*=:::==:\u001b[0m", "  \u001b[38;2;248;250;252m            :  .                                             :.:\u001b[0m", "  \u001b[38;2;248;250;252m                                                           :=-=######*++=+=++=*=\u001b[0m", "  \u001b[38;2;248;250;252m                                                              #++-+===--::..::::\u001b[0m", "  \u001b[38;2;248;250;252m                                                               ::-.\u001b[0m", "", ""], ["", "", "  \u001b[38;2;248;250;252m+++++++*###*+=-.\u001b[0m", "  \u001b[38;2;248;250;252m-::::::.:=@@@@*#*=-.\u001b[0m", "  \u001b[38;2;248;250;252m.. .      .-+#*=:::==:\u001b[0m", "  \u001b[38;2;248;250;252m               :  .                    \u001b[0m\u001b[1m\u001b[38;2;34;197;94mH\u001b[0m\u001b[38;2;248;250;252m                  :.:\u001b[0m", "  \u001b[38;2;248;250;252m                                                        :=-=######*++=+=++=*=+++\u001b[0m", "  \u001b[38;2;248;250;252m                                                           #++-+===--::..::::---\u001b[0m", "  \u001b[38;2;248;250;252m                                                            ::-.               .\u001b[0m", "", ""], ["", "", "  \u001b[38;2;248;250;252m+**+++++++*###*+=-.\u001b[0m", "  \u001b[38;2;248;250;252m===-::::::.:=@@@@*#*=-.\u001b[0m", "  \u001b[38;2;248;250;252m..... .      .-+#*=:::==:\u001b[0m", "  \u001b[38;2;248;250;252m                  :  .                \u001b[0m\u001b[1m\u001b[38;2;34;197;94mHell\u001b[0m\u001b[38;2;248;250;252m             :.:\u001b[0m", "  \u001b[38;2;248;250;252m                                                     :=-=######*++=+=++=*=++++++\u001b[0m", "  \u001b[38;2;248;250;252m                                                        #++-+===--::..::::---===\u001b[0m", "  \u001b[38;2;248;250;252m                                                         ::-.               ....\u001b[0m", "", ""], ["", "", "  \u001b[38;2;248;250;252m*+++**+++++++*###*+=-.\u001b[0m", "  \u001b[38;2;248;250;252m++====-::::::.:=@@@@*#*=-.\u001b[0m", "  \u001b[38;2;248;250;252m::...... .      .-+#*=:::==:\u001b[0m", "  \u001b[38;2;248;250;252m                     :  .           \u001b[0m\u001b[1m\u001b[38;2;34;197;94mHello PI\u001b[0m\u001b[38;2;248;250;252m        :.:\u001b[0m", "  \u001b[38;2;248;250;252m                                                  :=-=######*++=+=++=*=+++++++*+\u001b[0m", "  \u001b[38;2;248;250;252m                                                     #++-+===--::..::::---====++\u001b[0m", "  \u001b[38;2;248;250;252m                                                      ::-.               ......:\u001b[0m", "", ""], ["", "", "  \u001b[38;2;248;250;252m  +*+++**+++++++*###*+=-.\u001b[0m", "  \u001b[38;2;248;250;252m  +++====-::::::.:=@@@@*#*=-.\u001b[0m", "  \u001b[38;2;248;250;252m  :::...... .      .-+#*=:::==:\u001b[0m", "  \u001b[38;2;248;250;252m                        :  .        \u001b[0m\u001b[1m\u001b[38;2;34;197;94mHello PI\u001b[0m\u001b[38;2;248;250;252m     :.:\u001b[0m", "  \u001b[38;2;248;250;252m                                               :=-=######*++=+=++=*=+++++++*++\u001b[0m", "  \u001b[38;2;248;250;252m                                                  #++-+===--::..::::---====+++\u001b[0m", "  \u001b[38;2;248;250;252m                                                   ::-.               ......::\u001b[0m", "", ""], ["", "", "  \u001b[38;2;248;250;252m    +*+++**+++++++*###*+=-.\u001b[0m", "  \u001b[38;2;248;250;252m    +++====-::::::.:=@@@@*#*=-.\u001b[0m", "  \u001b[38;2;248;250;252m    :::...... .      .-+#*=:::==:\u001b[0m", "  \u001b[38;2;248;250;252m                          :  .    \u001b[0m\u001b[1m\u001b[38;2;56;189;248m*\u001b[0m \u001b[1m\u001b[38;2;34;197;94mHello PI\u001b[0m \u001b[1m\u001b[38;2;56;189;248m*\u001b[0m\u001b[38;2;248;250;252m :.:\u001b[0m", "  \u001b[38;2;248;250;252m                                             :=-=######*++=+=++=*=+++++++*++\u001b[0m", "  \u001b[38;2;248;250;252m                                                #++-+===--::..::::---====+++\u001b[0m", "  \u001b[38;2;248;250;252m                                                 ::-.               ......::\u001b[0m", "", ""], ["", "", "  \u001b[38;2;248;250;252m     +*+++**+++++++*###*+=-.\u001b[0m", "  \u001b[38;2;248;250;252m     +++====-::::::.:=@@@@*#*=-.\u001b[0m", "  \u001b[38;2;248;250;252m     :::...... .      .-+#*=:::==:\u001b[0m", "  \u001b[38;2;248;250;252m                           :  .   \u001b[0m\u001b[1m\u001b[38;2;56;189;248m*\u001b[0m \u001b[1m\u001b[38;2;34;197;94mHello PI\u001b[0m \u001b[1m\u001b[38;2;56;189;248m*\u001b[0m\u001b[38;2;248;250;252m:.:\u001b[0m", "  \u001b[38;2;248;250;252m                                            :=-=######*++=+=++=*=+++++++*++\u001b[0m", "  \u001b[38;2;248;250;252m                                               #++-+===--::..::::---====+++\u001b[0m", "  \u001b[38;2;248;250;252m                                                ::-.               ......::\u001b[0m", "", ""]];
    let i = 0;
    const interval = setInterval(() => {
      if (i >= frames.length) {
        clearInterval(interval);
        setTimeout(() => {
          process.stdout.write("\x1b[?25h\x1b[2J\x1b[H");
          process.exit(0);
        }, 220);
        return;
      }
      process.stdout.write("\x1b[H\x1b[2K\n\n");
      for (const line of frames[i]) {
        process.stdout.write(line + "\n");
      }
      i++;
    }, 75);
    '
    tput cnorm 2>/dev/null || true
fi

exec pi -e "$REPO_DIR" "$@"
